public class PlayCalculator {
    public double calculateAmount(Performance performance, Play play) {
        switch (play.getType()) {
            case "tragedy":
                double amount = 40000;
                if (performance.getAudience() > 30) {
                    amount += 1000 * (performance.getAudience() - 30);
                }
                return amount;
            case "comedy":
                double baseAmount = 30000;
                if (performance.getAudience() > 20) {
                    baseAmount += 10000 + 500 * (performance.getAudience() - 20);
                }
                return baseAmount + 300 * performance.getAudience();
            default:
                throw new IllegalArgumentException("Unknown play type: " + play.getType());
        }
    }

    public int calculateVolumeCredits(Performance performance, Play play) {
        int credits = Math.max(performance.getAudience() - 30, 0);
        if ("comedy".equals(play.getType())) {
            credits += Math.floor(performance.getAudience() / 5);
        }
        return credits;
    }
}

public class StatementGenerator {
    public String generateStatement(Invoice invoice, Map<String, Play> plays) {
        PlayCalculator calculator = new PlayCalculator();
        double totalAmount = 0;
        int totalCredits = 0;
        StringBuilder result = new StringBuilder("Statement for " + invoice.getCustomer() + "\n");

        for (Performance performance : invoice.getPerformances()) {
            Play play = plays.get(performance.getPlayID());
            if (play == null) {
                throw new IllegalArgumentException("Unknown play: " + performance.getPlayID());
            }
            double performanceAmount = calculator.calculateAmount(performance, play);
            int performanceCredits = calculator.calculateVolumeCredits(performance, play);
            totalAmount += performanceAmount;
            totalCredits += performanceCredits;
            result.append(String.format(" %s: %s (%d seats)\n",
                    play.getName(), NumberFormat.getCurrencyInstance(Locale.US).format(performanceAmount / 100),
                    performance.getAudience()));
        }

        result.append(String.format("Amount owed is %s\n",
                NumberFormat.getCurrencyInstance(Locale.US).format(totalAmount / 100)));
        result.append(String.format("You earned %d credits\n", totalCredits));

        return result.toString();
    }
}
